INSERT INTO collection_pages VALUES('5f1f41eef658ea5c01e272971437e2762c5ba7ef6eaf98971bf382aa3ae8303b','dc2a6283f6006bb9d52d56943a522a5e57e59f0f99fe73b71208c3b342ebde84','{"hasNext":false,"items":[{"author":{"account":{"login":"h11g","providerType":"User"},"email":"wq.huang@aftership.com","name":"huangwq"},"authoredDate":"2026-08-19T09:43:35Z","committedDate":"2026-08-19T09:43:35Z","committer":{"account":{"login":"h11g","providerType":"User"},"email":"wq.huang@aftership.com","name":"huangwq"},"observedAt":"2026-10-09T00:16:45.129Z","repositoryId":1339383846,"sha":"2f5ca7d22e8b4b48d99cd7c2c9065c3a84a38f82"}],"observedAt":"2026-10-09T00:16:45.129Z","raw":[{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/19600972?v=4","events_url":"https://api.github.com/users/h11g/events{/privacy}","followers_url":"https://api.github.com/users/h11g/followers","following_url":"https://api.github.com/users/h11g/following{/other_user}","gists_url":"https://api.github.com/users/h11g/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/h11g","id":19600972,"login":"h11g","node_id":"MDQ6VXNlcjE5NjAwOTcy","organizations_url":"https://api.github.com/users/h11g/orgs","received_events_url":"https://api.github.com/users/h11g/received_events","repos_url":"https://api.github.com/users/h11g/repos","site_admin":false,"starred_url":"https://api.github.com/users/h11g/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/h11g/subscriptions","type":"User","url":"https://api.github.com/users/h11g","user_view_type":"public"},"comments_url":"https://api.github.com/repos/h11g/mf-vite-loaded-first-repro/commits/2f5ca7d22e8b4b48d99cd7c2c9065c3a84a38f82/comments","commit":{"author":{"date":"2026-08-19T09:43:35Z","email":"wq.huang@aftership.com","name":"huangwq"},"comment_count":0,"committer":{"date":"2026-08-19T09:43:35Z","email":"wq.huang@aftership.com","name":"huangwq"},"message":"Minimal repro: loaded-first deferred remote proxy throws out of module evaluation\n\n@module-federation/vite@1.20.7, production build, browser, no framework.\n\nWith shareStrategy: ''loaded-first'' the remote resolves to\n__mfCreateDeferredRemoteProxy(). Its get trap throws the pending load Promise as\na React-Suspense signal, but the consumer bindings read the namespace during\nmodule evaluation, so the throw escapes and rejects the entry''s import(). The\napp never boots and the rejection reason is a Promise rather than an Error, so\nthere is no usable stack.\n\nTwo variants, both reproducing: a plain named import (the read is in generated\ncode) and ''import * as ns'' with ''export const {x} = ns'' (the read is in user\nsource). Dropping the shareStrategy line makes both pass.\n\nSee README.md and proposed-fix.diff.\n\nRefs: https://github.com/module-federation/vite/issues/1096","tree":{"sha":"a3a3f6f3305f39f1f90fa332d7db3893c174a865","url":"https://api.github.com/repos/h11g/mf-vite-loaded-first-repro/git/trees/a3a3f6f3305f39f1f90fa332d7db3893c174a865"},"url":"https://api.github.com/repos/h11g/mf-vite-loaded-first-repro/git/commits/2f5ca7d22e8b4b48d99cd7c2c9065c3a84a38f82","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/19600972?v=4","events_url":"https://api.github.com/users/h11g/events{/privacy}","followers_url":"https://api.github.com/users/h11g/followers","following_url":"https://api.github.com/users/h11g/following{/other_user}","gists_url":"https://api.github.com/users/h11g/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/h11g","id":19600972,"login":"h11g","node_id":"MDQ6VXNlcjE5NjAwOTcy","organizations_url":"https://api.github.com/users/h11g/orgs","received_events_url":"https://api.github.com/users/h11g/received_events","repos_url":"https://api.github.com/users/h11g/repos","site_admin":false,"starred_url":"https://api.github.com/users/h11g/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/h11g/subscriptions","type":"User","url":"https://api.github.com/users/h11g","user_view_type":"public"},"html_url":"https://github.com/h11g/mf-vite-loaded-first-repro/commit/2f5ca7d22e8b4b48d99cd7c2c9065c3a84a38f82","node_id":"C_kwDOT9VgJtoAKDJmNWNhN2QyMmU4YjRiNDhkOTljZDdjMmM5MDY1YzNhODRhMzhmODI","parents":[],"sha":"2f5ca7d22e8b4b48d99cd7c2c9065c3a84a38f82","url":"https://api.github.com/repos/h11g/mf-vite-loaded-first-repro/commits/2f5ca7d22e8b4b48d99cd7c2c9065c3a84a38f82"}],"requestUrl":"https://api.github.com/repos/h11g/mf-vite-loaded-first-repro/commits?per_page=100&page=1&sha=2f5ca7d22e8b4b48d99cd7c2c9065c3a84a38f82&since=2025-03-31T23%3A59%3A59.000Z&until=2026-10-08T16%3A19%3A35.172Z"}');
